import { type Address, type BillingAddress, type Invoice, type InvoiceItem, type InvoiceResponse, InvoiceStatus, type Line } from './models'

export function mapInvoiceResponseToInvoice(source: InvoiceResponse): Invoice {
  return {
    id: source.invoice_id,
    issuedAt: new Date(source.issued_at),
    dueDate: new Date(source.due_date),
    status: toInvoiceStatus(source.status),
    total: source.total_cents > 0 ? Math.round(source.total_cents / 100) : 0,
    currency: source.currency,
    notes: source.notes == null ? undefined : String(source.notes) ?? 'none',
    customerId: source.customer.customer_id,
    customerName: (`${source.customer.first_name.toUpperCase()}${' '}${source.customer.last_name}`).trim(),
    customerEmail: source.customer.email_address,
    billingAddress: mapBillingAddressToAddress(source.customer.billing_address),
    items: source.lines.map(mapLineToInvoiceItem),
    isPaid: source.paid,
    createdBy: 'importer',
  }
}

export function mapBillingAddressToAddress(source: BillingAddress): Address {
  return {
    street: source.street,
    city: source.city,
    postalCode: source.zip_code,
    // TODO: no value for "countryCode" in the mapping
    countryCode: '',
  }
}

export function mapLineToInvoiceItem(source: Line): InvoiceItem {
  return {
    sku: source.sku,
    description: source.description,
    quantity: source.qty,
    unitPrice: source.unit_price_cents / 100,
    taxRate: source.tax_rate,
  }
}

function toInvoiceStatus(value: string): InvoiceStatus {
  switch (value) {
    case 'paid':
      return InvoiceStatus.PAID
    default:
      return InvoiceStatus.DRAFT
  }
}

