import java.math.BigDecimal;
import java.math.MathContext;
import java.util.Objects;

public final class InvoiceResponseMapper {

    private InvoiceResponseMapper() {
    }

    public static Invoice toInvoice(InvoiceResponse source) {
        if (source == null) {
            return null;
        }
        return new Invoice(
                source.getInvoiceId(),
                source.getIssuedAt(),
                source.getDueDate(),
                toInvoiceStatus(source.getStatus()),
                source.getTotalCents() > 0 ? BigDecimal.valueOf(Math.round((double) source.getTotalCents() / 100.0)) : new BigDecimal("0"),
                source.getCurrency(),
                Objects.requireNonNullElse(source.getNotes() != null ? String.valueOf(source.getNotes()) : null, "none"),
                (long) source.getCustomer().getCustomerId(),
                (String.valueOf(source.getCustomer().getFirstName().toUpperCase()) + String.valueOf(" ") + String.valueOf(source.getCustomer().getLastName())).strip(),
                source.getCustomer().getEmailAddress(),
                toAddress(source.getCustomer().getBillingAddress()),
                source.getLines().stream().map(InvoiceResponseMapper::toInvoiceItem).toList(),
                source.getPaid(),
                "importer"
        );
    }

    public static Address toAddress(BillingAddress source) {
        if (source == null) {
            return null;
        }
        return new Address(
                source.getStreet(),
                source.getCity(),
                source.getZipCode(),
                // TODO: no value for "countryCode" in the mapping
                ""
        );
    }

    public static InvoiceItem toInvoiceItem(Line source) {
        if (source == null) {
            return null;
        }
        return new InvoiceItem(
                source.getSku(),
                source.getDescription(),
                Math.toIntExact(source.getQty()),
                BigDecimal.valueOf(source.getUnitPriceCents()).divide(BigDecimal.valueOf(100), MathContext.DECIMAL128),
                source.getTaxRate()
        );
    }

    private static InvoiceStatus toInvoiceStatus(String value) {
        return switch (value) {
            case "paid" -> InvoiceStatus.PAID;
            default -> InvoiceStatus.DRAFT;
        };
    }
}

import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.mapstruct.MappingConstants;
import org.mapstruct.ValueMapping;

import java.math.BigDecimal;
import java.math.MathContext;

@Mapper(imports = {BigDecimal.class, MathContext.class})
public interface InvoiceResponseMapper {

    @Mapping(target = "id", source = "invoiceId")
    @Mapping(target = "total", expression = "java(source.getTotalCents() > 0 ? BigDecimal.valueOf(Math.round((double) source.getTotalCents() / 100.0)) : new BigDecimal(\"0\"))")
    @Mapping(target = "notes", defaultValue = "none")
    @Mapping(target = "customerId", source = "customer.customerId")
    @Mapping(target = "customerName", expression = "java((String.valueOf(source.getCustomer().getFirstName().toUpperCase()) + String.valueOf(\" \") + String.valueOf(source.getCustomer().getLastName())).strip())")
    @Mapping(target = "customerEmail", source = "customer.emailAddress")
    @Mapping(target = "billingAddress", source = "customer.billingAddress")
    @Mapping(target = "items", source = "lines")
    @Mapping(target = "isPaid", source = "paid")
    @Mapping(target = "createdBy", constant = "importer")
    Invoice toInvoice(InvoiceResponse source);

    @Mapping(target = "postalCode", source = "zipCode")
    // TODO: no value for "countryCode" in the mapping
    @Mapping(target = "countryCode", ignore = true)
    Address toAddress(BillingAddress source);

    @Mapping(target = "quantity", source = "qty")
    @Mapping(target = "unitPrice", expression = "java(BigDecimal.valueOf(source.getUnitPriceCents()).divide(BigDecimal.valueOf(100), MathContext.DECIMAL128))")
    InvoiceItem toInvoiceItem(Line source);

    @ValueMapping(source = "paid", target = "PAID")
    @ValueMapping(source = MappingConstants.ANY_REMAINING, target = "DRAFT")
    InvoiceStatus toInvoiceStatus(String value);
}

