	return mapInvoiceResponseToInvoice(source)
}

func mapInvoiceResponseToInvoice(source InvoiceResponse) Invoice {
	return Invoice{
		ID: source.InvoiceID,
		IssuedAt: source.IssuedAt,
		DueDate: source.DueDate,
		Status: toInvoiceStatus(source.Status),
		Total: func() float64 {
			if source.TotalCents > 0 {
				return math.Round(float64(source.TotalCents) / 100.0)
			}
			return 0.0
		}(),
		Currency: source.Currency,
		Notes: pointerTo(valueOr(mapPointer(source.Notes, func(value any) string {
			return fmt.Sprint(value)
		}), "none")),
		CustomerID: source.Customer.CustomerID,
		CustomerName: strings.TrimSpace(fmt.Sprint(strings.ToUpper(source.Customer.FirstName), " ", source.Customer.LastName)),
		CustomerEmail: source.Customer.EmailAddress,
		BillingAddress: mapBillingAddressToAddress(source.Customer.BillingAddress),
		Items: mapSlice(source.Lines, mapLineToInvoiceItem),
		IsPaid: source.Paid,
		CreatedBy: "importer",
	}
}

func mapBillingAddressToAddress(source BillingAddress) Address {
	return Address{
		Street: source.Street,
		City: source.City,
		PostalCode: source.ZipCode,
		// TODO: no value for "countryCode" in the mapping
		CountryCode: "",
	}
}

func mapLineToInvoiceItem(source Line) InvoiceItem {
	return InvoiceItem{
		Sku: source.Sku,
		Description: source.Description,
		Quantity: int32(source.Qty),
		UnitPrice: float64(source.UnitPriceCents) / 100.0,
		TaxRate: source.TaxRate,
	}
}

func toInvoiceStatus(value string) InvoiceStatus {
	switch value {
	case "paid":
		return InvoiceStatusPaid
	default:
		return InvoiceStatusDraft
	}
}

func mapPointer[T, R any](value *T, mapValue func(T) R) *R {
	if value == nil {
		return nil
	}
	result := mapValue(*value)
	return &result
}

func mapSlice[T, R any](items []T, mapItem func(T) R) []R {
	if items == nil {
		return nil
	}
	result := make([]R, len(items))
	for index, item := range items {
		result[index] = mapItem(item)
	}
	return result
}

func pointerTo[T any](value T) *T {
	return &value
}

func valueOr[T any](value *T, fallback T) T {
	if value == nil {
		return fallback
	}
	return *value
}

