use rust_decimal::Decimal;
use crate::models::{Address, BillingAddress, Invoice, InvoiceItem, InvoiceResponse, InvoiceStatus, Line};

impl From<&InvoiceResponse> for Invoice {
    fn from(source: &InvoiceResponse) -> Self {
        Self {
            id: source.invoice_id.clone(),
            issued_at: source.issued_at.clone(),
            due_date: source.due_date.clone(),
            status: to_invoice_status(&source.status),
            total: if source.total_cents > 0 { Decimal::try_from((source.total_cents as f64 / 100.0).round()).expect("number out of range") } else { Decimal::from(0) },
            currency: source.currency.clone(),
            notes: Some(source.notes.as_ref().map(|value| value.to_string()).unwrap_or_else(|| "none".to_string())),
            customer_id: source.customer.customer_id,
            customer_name: format!("{}{}{}", source.customer.first_name.to_uppercase(), " ".to_string(), source.customer.last_name).trim().to_string(),
            customer_email: source.customer.email_address.clone(),
            billing_address: Address::from(&source.customer.billing_address),
            items: source.lines.iter().map(InvoiceItem::from).collect(),
            is_paid: source.paid,
            created_by: "importer".to_string(),
        }
    }
}

impl From<&BillingAddress> for Address {
    fn from(source: &BillingAddress) -> Self {
        Self {
            street: source.street.clone(),
            city: source.city.clone(),
            postal_code: source.zip_code.clone(),
            country_code: todo!("no value for countryCode in the mapping"),
        }
    }
}

impl From<&Line> for InvoiceItem {
    fn from(source: &Line) -> Self {
        Self {
            sku: source.sku.clone(),
            description: source.description.clone(),
            quantity: source.qty as i32,
            unit_price: Decimal::from(source.unit_price_cents) / Decimal::from(100),
            tax_rate: source.tax_rate,
        }
    }
}

fn to_invoice_status(value: &str) -> InvoiceStatus {
    match value {
        "paid" => InvoiceStatus::PAID,
        _ => InvoiceStatus::DRAFT,
    }
}

